    ui.Text(ShortInfo(selected.Goal,62),right,body+81,Cyan,12);ui.Text($"Shield {selected.Fit.Shield:0}/{selected.Fit.MaxShield:0} | Armor {selected.Fit.Armor:0} | Hull {selected.Fit.Hull:0}",right,body+108,White,12);
    ui.Text($"Cap {selected.Fit.Cap:0}/{selected.Fit.MaxCap:0} | wage {selected.Wage:0} CR / hour",right,body+133,Gold,12);
    ui.Button(new(right,body+167,185,28),selected.Contracted?"DISMISS AT STATION":"HIRE / 350 CR",()=>{bool ok=selected.Contracted?world.DismissPopulationPilotC(selected.Id):world.HirePopulationPilotC(selected.Id);if(!ok)world.Say("Contract unavailable: dock locally, check pilot role, crew limit and wallet.");},"Hire or dismiss population pilot");
    ui.Button(new(right+195,body+167,170,28),"PILOT INFORMATION",()=>ShowPopulationInfoC(selected),"Open population pilot information");
    ui.Button(new(right,body+203,185,28),state.Watchlist.Contains(selected.Id)?"REMOVE WATCHLIST":"ADD WATCHLIST",()=>{if(!state.Watchlist.Remove(selected.Id))state.Watchlist.Add(selected.Id);},"Toggle population watchlist");
    ui.Button(new(right+195,body+203,170,28),"REPLACE LOST SHIP",()=>{if(!world.ReplacePopulationShipC(selected.Id))world.Say("Replacement needs a lost ship and stocked hull, gun and 120 ammunition.");},"Replace population ship using real stock");
    int yy=body+246;ui.Text("RECENT MEMORY",right,yy,Cyan,12);foreach(var memory in selected.Memory.TakeLast(6).Reverse()){yy+=23;ui.Text(ShortInfo(memory,64),right,yy,Muted,11);}
   }else ui.Text("Select a pilot to inspect their contract, fit and history.",right,body,Muted,12);
   if(populationTabC==1){int yy=window.Y+window.Height-105;foreach(var order in new[]{"Follow","Hold","Attack","Mine","Recall","Scout"}){var command=order;ui.Button(new(x+Array.IndexOf(new[]{"Follow","Hold","Attack","Mine","Recall","Scout"},order)*110,yy,104,27),order,()=>{if(!world.OrderPopulationC(command))world.Say("Order requires paid active crew and a valid selected target for Attack or Mine.");},"Fleet broadcast / "+order);}ui.Button(new(right+380,body+167,145,28),"FORMATION: "+state.Formation,()=>state.Formation=state.Formation=="Arrow"?"Wall":state.Formation=="Wall"?"Sphere":"Arrow","Cycle population formation");}
  }
  else if(populationTabC==2){
   ui.Text("SHIPMENTS / ROUTE / STATE",x,body,Cyan,12);int yy=body+29;foreach(var op in state.Shipments.Where(o=>populationAllC||o.System==world.SystemId).TakeLast(14).Reverse()){var shipment=op;ui.Button(new(x,yy,width-15,31),ShortInfo(op.Id+" / "+world.PopulationPilot(op.Pilot)?.Name+" / "+op.State+" / cargo "+op.Cargo.Values.Sum()+" / leg "+(op.Leg+1)+" of "+op.Route.Count,130),()=>{world.SelectedId=world.Targets.Any(t=>t.Id==shipment.Pilot)?shipment.Pilot:"";world.Say("Shipment "+shipment.State+" at "+DemoWorld.ResolveSystem43(shipment.System).Name+"; no remote targeting knowledge granted.");},"Track shipment / "+op.Id);yy+=37;}
   ui.Button(new(x+width-210,body-4,205,28),"ARRANGE SUPPLY CONVOY",()=>{if(world.ArrangePopulationConvoyC()==null)world.Say("Convoy needs local docking, an available hauler, trader stock and a funded buyer.");},"Arrange population supply convoy");ui.Text("Cargo is reserved once. Loss refunds buyer escrow and leaves one persistent wreck.",x,window.Y+window.Height-51,Muted,12);
  }
  else if(populationTabC==3){
   ui.Text("BUSINESSES / WALLET / SUPPLY",x,body,Cyan,12);int yy=body+29;foreach(var b in state.Businesses.Where(b=>populationAllC||world.LocationSystem(b.Station)==world.SystemId).Skip(populationPageC*12).Take(12)){var business=b;ui.Button(new(x,yy,right-x-20,32),ShortInfo(b.Kind+" / "+world.LocationName(b.Station)+" / "+b.State,62),()=>populationSelectedC=business.Id,"Select population business / "+b.Id,populationSelectedC==b.Id);yy+=38;}
   var selected=state.Businesses.FirstOrDefault(b=>b.Id==populationSelectedC);if(selected!=null){ui.Text(selected.Name,right,body,White,16);ui.Text($"Funds {selected.Wallet:0.00} CR / runs {selected.Runs} / lost shipments {selected.LostShipments}",right,body+31,Gold,12);ui.Text($"Shortage index {selected.Shortages} / {selected.State}",right,body+58,Cyan,12);int ry=body+87;foreach(var c in selected.Stock.OrderBy(s=>s.Key).Take(12)){ui.Text(ShortInfo(DemoWorld.ItemName(c.Key),39)+": "+c.Value.ToString("0"),right,ry,Muted,12);ry+=24;}
    ui.Button(new(right,body+392,190,28),"SELL 100 AMMO",()=>{if(!world.SupplyBusinessC(selected.Id,"ammo",100))world.Say("Supply sale needs local docking, hangar ammunition and buyer funds.");},"Sell real supplies to population business");ui.Button(new(right+200,body+392,150,28),"OPEN MARKET",()=>Open(ViewMode.Market),"Open market from population business");
   }else ui.Text("Select a business to see real inventory and procurement pressure.",right,body,Muted,12);
  }
  else{
   var rows=new[]{("Visited sectors",state.Sectors.Count.ToString()),("Persistent pilots / crew",state.Pilots.Count+" / "+state.Pilots.Count(p=>p.Contracted)),("Managed opening cash",state.OpeningMoney.ToString("0.00")+" CR"),("External net cash",state.ExternalNet.ToString("0.00")+" CR"),("Tax / service sinks",state.Sinks.ToString("0.00")+" CR"),("Current cash + escrow",world.PopulationMoneyC.ToString("0.00")+" CR"),("Money reconciliation",world.PopulationMoneyErrorC.ToString("0.00")+" CR"),("Ore extracted / reserve left",state.OreExtracted+" / "+state.Sectors.Values.Sum(s=>s.Resource)),("Produced / consumed units",state.GoodsProduced+" / "+state.GoodsConsumed),("Finite legacy market", "Existing opening stock is retained; no synthetic fills here."),("Emergency stabilization", "OFF: no free stock, cash, hulls or NPC reships.")};int yy=body;foreach(var row in rows){ui.Text(row.Item1,x,yy,Cyan,12);ui.Text(row.Item2,x+240,yy,White,12);yy+=31;}
   ui.Text("RECENT ACCOUNTING / EVENTS",right,body,Cyan,12);int ry=body+30;foreach(var e in state.Journal.TakeLast(14).Reverse()){ui.Text(ShortInfo($"T{e.Tick} {e.Event} / {e.Item} {e.Quantity:0} / {e.Money:0.00} CR",66),right,ry,Muted,11);ry+=26;}
  }
 }
 void ShowPopulationInfoC(PilotC p){var entry=new InformationEntry{Key="population-c/"+p.Id,Id=p.Id,Name=p.Name,Kind="Capsuleer",Group=p.Role,Description="Persistent Starlight pilot; information reflects current known simulation state."};entry.Add("Description",entry.Description);entry.Add("Biography","Role",p.Role);entry.Add("Biography","Legal state",p.LegalState);entry.Add("Biography","Home",world.LocationName(p.Home));entry.Add("Biography","Losses",p.Losses.ToString());entry.Add("Fit","Instance",p.Fit.InstanceId);foreach(var m in FittingLayoutModel.Installed(p.Fit))entry.Add("Fit",m.Name,m.Bank+" / "+(m.Burnt?"burnt":m.Online==false?"offline":"online"));foreach(var sk in p.Fit.SkillLevels)entry.Add("Skills",SkillCatalog.ById[sk.Key].Name,sk.Value.ToString());foreach(var memory in p.Memory)entry.Add("Memory",memory);informationSnapshots[entry.Key]=entry;ShowInformation(entry.Key);}
 void SetupPopulationCaptureC(){world.NewGame(0);world.WalletFunds=100000;world.EnsurePopulationC();populationSelectedC=world.Population.Pilots.First(p=>p.Role=="Tackler").Id;desktop.Clear();OpenPopulationC();if(captureScene=="stage-c-reports"){world.AdvanceHours(4);populationTabC=4;}if(captureScene=="stage-c-fleet"){foreach(var p in world.Population.Pilots.Where(p=>p.Role is "Scout" or "Tackler" or "Logi"))world.HirePopulationPilotC(p.Id);populationTabC=1;}}
 int populationUiChecksC;
 void RunPopulationUiChecksC(int frame){void Check(bool value,string name){if(!value)throw new Exception("STAGE C UI FAIL: "+name);populationUiChecksC++;Console.WriteLine("STAGE C UI PASS: "+name);}void Click(string tip)=>TestClick(ui.Hits.Last(h=>h.Tip==tip).Rect.Center.ToVector2());switch(frame){case 0:Check(desktop.Any(w=>w.Kind==ViewMode.Population),"Population window opens");Click("Hire or dismiss population pilot");Check(world.Population.Pilots.Any(p=>p.Contracted),"Hiring click creates paid contract");break;case 1:Click("Population tab / Crew & watchlist");break;case 2:Click("Fleet broadcast / Hold");Check(world.Population.Pilots.Single(p=>p.Contracted).Order=="Hold","Crew broadcast changes actual orders");break;case 3:Click("Population tab / Pilots");populationSelectedC=world.Population.Pilots.First(p=>p.Role=="Tackler").Id;break;case 4:Click("Open population pilot information");Check(desktop.Last().InfoKey.StartsWith("population-c/"),"Pilot information opens");break;case 5:Check(ResolveInformation(desktop.Last().InfoKey)?.Tabs.ContainsKey("Fit")==true,"Pilot info exposes owned fitting");desktop.RemoveAll(w=>w.Kind==ViewMode.Information);break;case 6:Click("Population tab / Businesses");populationSelectedC=world.Population.Businesses.First().Id;world.Hangar["ammo"]=100;break;case 7:Click("Sell real supplies to population business");Check(world.Hangar["ammo"]==0,"Business supply click consumes real inventory");break;case 8:Click("Population tab / Operations");break;case 9:Click("Arrange population supply convoy");Check(world.Population.Shipments.Any(o=>o.State=="Transit"),"Convoy control reserves actual stock and buyer escrow");Click("Population tab / Reports");Check(world.PopulationMoneyErrorC==0,"UI operations preserve money conservation");break;case 10:Check(ui.Hits.Any(h=>h.Tip=="Population tab / Operations"),"All population tabs remain available");Console.WriteLine(populationUiChecksC+" Stage C UI checks passed.");break;}}
}
public sealed partial class DemoWorld
{
 public ShipmentC? ArrangePopulationConvoyC(){if(!Docked)return null;EnsurePopulationC();var seller=Population.Businesses.FirstOrDefault(b=>b.Station==StationKey44&&b.Kind=="Trader");var buyer=Population.Businesses.Where(b=>b.Kind=="Factory"&&b.Id!=seller?.Id).OrderByDescending(b=>LocationSystem(b.Station)!=SystemId).FirstOrDefault();return seller==null||buyer==null?null:DispatchShipmentC(seller.Id,buyer.Id,"ammo",20);}
 public bool SupplyBusinessC(string id,string item,int quantity){var b=Population.Businesses.FirstOrDefault(b=>b.Id==id);if(!Docked||b==null||b.Station!=StationKey44||quantity<=0||StackCount(item,true)<quantity||item!="ammo")return false;decimal gross=Math.Round(ItemCatalog.Get(item).Price*.9m,2)*quantity;if(b.Wallet<gross)return false;decimal tax=Math.Round(gross*SalesTax,2);ChangeStack(item,true,-quantity);b.Wallet-=gross;b.Stock[item]=b.Stock.GetValueOrDefault(item)+quantity;WalletChange(gross-tax,"Supply sale / "+b.Name);Population.ExternalNet-=gross;PopulationLogC("Player supply",b.Id,item,quantity,gross);return true;}
}
